    df["Hire_Date_dt"] = pd.to_datetime(df["Hire_Date"], errors="coerce")
    df["Termination_Date_dt"] = pd.to_datetime(df["Termination_Date"], errors="coerce")

    mask_in_force = (
        (df["Hire_Date_dt"] <= ref_date) &
        (
            df["Termination_Date_dt"].isna() |
            (df["Termination_Date_dt"] > ref_date)
        ) &
        (~df["Employment_Status"].str.lower().eq("terminated") | df["Termination_Date_dt"].notna()) &
        (~df["Worker_Type"].str.lower().isin(contractor_types)) &
        (df.get("left_date_unknown", pd.Series("no", index=df.index)).str.lower() != "yes") &
        (df.get("row_kind", pd.Series("counted", index=df.index)).isin(["counted", "netted"]))
    )

    in_force_2025 = df[mask_in_force]

