        in_force_2025.groupby("Department")["Employee_ID"]
        .nunique()
        .reset_index()
        .rename(columns={"Employee_ID": "headcount"})
        .sort_values("headcount", ascending=False)
    )

    result["segments"].append({
        "segment_column": "Department",
        "metric_column": "Employee_ID",
        "aggregation": "count",
        "label": "headcount_end_2025_excl_contractors",
