        "Employment_Status not Terminated without a termination date, Worker_Type not in contractor set, "
        "left_date_unknown != yes; distinct Employee_IDs counted."
    )
except Exception as e:
    result["segments"].append({
        "segment_column": "Department",
        "metric_column": "Employee_ID",
        "aggregation": "count",
        "label": "headcount_end_2025_excl_contractors_ERROR",
